        const routerNew = new EVRPTWBatterySwappingDecayRouter({ nominalBatteryKwh: 40.0, cycleCount: 0 });
        const routerUsed = new EVRPTWBatterySwappingDecayRouter({ nominalBatteryKwh: 40.0, cycleCount: 100 });
